CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, role TEXT NOT NULL, status TEXT NOT NULL, preferences JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS broker_connections (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), broker TEXT NOT NULL, credential_reference TEXT NOT NULL, status TEXT NOT NULL, last_health_check TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS instruments (id TEXT PRIMARY KEY, exchange TEXT NOT NULL, symbol TEXT NOT NULL, segment TEXT NOT NULL, lot_size INTEGER NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS strategies (id TEXT NOT NULL, version INTEGER NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), rules JSONB NOT NULL, risk_config JSONB NOT NULL, promotion_state TEXT NOT NULL, immutable BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (id, version));
CREATE TABLE IF NOT EXISTS risk_decisions (id TEXT PRIMARY KEY, signal_id TEXT NOT NULL, mode TEXT NOT NULL, decision TEXT NOT NULL, checks JSONB NOT NULL, reason TEXT NOT NULL, evaluated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, mode TEXT NOT NULL, instrument_id TEXT NOT NULL, side TEXT NOT NULL, quantity INTEGER NOT NULL, internal_reference TEXT UNIQUE NOT NULL, broker_order_id TEXT, status TEXT NOT NULL, filled_quantity INTEGER NOT NULL DEFAULT 0, remaining_quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS execution_events (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), event_type TEXT NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, reason TEXT, before_state JSONB, after_state JSONB, occurred_at TIMESTAMPTZ NOT NULL);